        {hero && <Link className="scard bk-trunk-card" href={`/products/${hero.slug}`} tabIndex={opened ? 0 : -1} aria-label={`Explore ${hero.name}, ${money(hero.pricePaise)}`}><img className="art" src={imageUrl(hero.image)} alt=""/><span className="cap"><b>EDITORIAL · {findMaker('Tathaastu')?.brand || 'SAMPLE'}</b><strong>{hero.name}</strong><small>{money(hero.pricePaise)} · sample catalogue</small></span></Link>}
