    <section className="bk-section" style={{paddingTop:8}}><div className="bk-sectionhead"><div><span className="bk-eyebrow">A gift for every kind of moment</span><h2>Start with the feeling.</h2></div></div><div className="bk-categories">{[['For a new beginning','Housewarmings, fresh starts'],['For the everyday','Little reasons to say thanks'],['For the host','Bring something thoughtful'],['For no occasion','Just because you thought of them']].map(([label,desc])=><Link className="bk-cat" key={label} href="/gift-finder"><span>{label}</span><small>{desc}</small></Link>)}</div></section>
