function ShopPage({ catalog, saved, toggle, makerOnly }: { catalog: Catalog; saved: string[]; toggle: (id:string)=>void; makerOnly?: string }) {
  const [query, setQuery] = useState('');
  const [category, setCategory] = useState('');
  const [maker, setMaker] = useState(makerOnly || '');
  const [budget, setBudget] = useState('');
  const [sort, setSort] = useState('curated');
  const makers = catalog.makers;
  const categories = [...new Set(catalog.products.map(p => p.category))];
  const matches = useMemo(() => catalog.products.filter(p => {
    const mk = makers.find(m => m.id === p.makerId);
    return (!maker || p.makerId === maker || mk?.slug === maker) &&
      (!category || p.category === category) &&
      (!budget || p.pricePaise <= Number(budget)) &&
      (!query || `${p.name} ${p.category} ${p.material} ${mk?.brand}`.toLowerCase().includes(query.toLowerCase()));
  }).sort((a,b) => sort === 'price-low' ? a.pricePaise - b.pricePaise : sort === 'price-high' ? b.pricePaise - a.pricePaise : sort === 'name' ? a.name.localeCompare(b.name) : 0), [catalog.products, makers, maker, category, budget, query, sort]);
  return <main><Seo title="The considered edit" description="Shop handmade gifts, home objects and thoughtful pieces from independent makers."/><header className="bk-pagehead"><span className="bk-eyebrow">An edit with a point of view</span><h1>The considered edit.</h1><p>Objects chosen for the care in their making, and the meaning they carry when given.</p>{catalog.sample && <p className="bk-status">Sample catalogue · indicative prices and product details</p>}</header><section className="bk-catalog"><div className="bk-toolbar"><div className="bk-filters"><label className="bk-search"><Search size={17}/><input aria-label="Search products" placeholder="Search objects, craft, material…" value={query} onChange={e=>setQuery(e.target.value)}/></label><select className="bk-select" aria-label="Filter by category" value={category} onChange={e=>setCategory(e.target.value)}><option value="">All crafts</option>{categories.map(c=><option key={c}>{c}</option>)}</select><select className="bk-select" aria-label="Filter by maker" value={maker} onChange={e=>setMaker(e.target.value)}><option value="">All makers</option>{makers.map(m=><option key={m.id} value={m.id}>{m.brand}</option>)}</select><select className="bk-select" aria-label="Filter by budget" value={budget} onChange={e=>setBudget(e.target.value)}><option value="">Any budget</option><option value="150000">Under ₹1,500</option><option value="300000">Under ₹3,000</option><option value="500000">Under ₹5,000</option></select></div><label>Sort <select className="bk-select" value={sort} onChange={e=>setSort(e.target.value)}><option value="curated">Curated</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="name">Name</option></select></label></div><p className="bk-muted">{matches.length} {matches.length === 1 ? 'piece' : 'pieces'} in this edit</p><ProductGrid products={matches} makers={makers} saved={saved} toggle={toggle}/></section></main>;
}
function MakersPage({ catalog }: { catalog: Catalog }) {
  return <main><Seo title="Meet the makers" description="Meet independent makers represented in the Baksa Tales sample catalogue."/><header className="bk-pagehead"><span className="bk-eyebrow">People behind the work</span><h1>Meet the makers.</h1><p>Start with the work itself. Maker stories here stay close to the details provided in each catalogue listing.</p>{catalog.sample && <p className="bk-status">Maker listings are sample catalogue entries.</p>}</header><section className="bk-catalog"><div className="bk-productgrid">{catalog.makers.map((m,i)=><article key={m.id} className="bk-panel" style={{padding:0,overflow:'hidden',margin:0}}><Link href={`/makers/${m.slug}`} style={{textDecoration:'none'}}><img src={imageUrl(m.image || ['t-bluelotus.webp','mu-box.webp','sv-sandhya.webp','an-range.webp'][i%4])} alt="" style={{width:'100%',height:290,objectFit:'cover',display:'block'}}/><div style={{padding:20}}><span className="bk-eyebrow">{m.craft}</span><h2 style={{fontSize:31,margin:'8px 0'}}>{m.brand}</h2><p className="bk-muted">{m.tagline}</p><span className="bk-textlink">Explore the story <ArrowRight size={15}/></span></div></Link></article>)}</div></section></main>;
}
function ProductPage({ catalog, product, makers, saved, toggle, add }: { catalog: Catalog; product?: Product; makers: Maker[]; saved: string[]; toggle:(id:string)=>void; add:(id:string,n:number)=>void }) {
  const [quantity, setQuantity] = useState(1);
  if (!product) return <main className="bk-formpage"><Seo title="Piece not found" description="This piece is not available in the current catalogue."/><span className="bk-eyebrow">Not in this edit</span><h1>We couldn’t find that piece.</h1><Link className="bk-btn" href="/shop">Return to the edit</Link></main>;
  const maker = makers.find(m => m.id === product.makerId);
  const related = catalog.products.filter(p => p.makerId === product.makerId && p.id !== product.id).slice(0,4);
  return <main><Seo title={product.name} description={`${product.name} from ${maker?.brand || 'an independent maker'} — explore its story in the Baksa Tales catalogue.`}/><section className="bk-product-main"><p className="bk-muted"><Link href="/">Home</Link> / <Link href="/shop">The edit</Link> / {product.name}</p><div className="bk-product-layout"><img className="bk-product-mainimg" src={imageUrl(product.image)} alt={product.name}/><div className="bk-product-info"><span className="bk-eyebrow">{product.category}</span><h1>{product.name}</h1>{maker && <p className="bk-product-maker">By <Link href={`/makers/${maker.slug}`}>{maker.brand}</Link> · {maker.craft}</p>}<p className="bk-product-price">{money(product.pricePaise)}</p>{product.sample && <p className="bk-product-sample">Sample catalogue · indicative price</p>}<p className="bk-product-desc">{product.description}</p><div className="bk-product-detailrow"><Package size={18}/><span>{product.material}</span></div><div className="bk-product-detailrow"><BookOpen size={18}/><span>Dispatch estimate: usually {product.dispatchDays} days before dispatch. Delivery timing depends on destination and carrier.</span></div><div className="bk-product-detailrow"><Check size={18}/><span>{product.stock > 0 ? 'Availability shown in sample catalogue' : 'Currently shown as unavailable'}</span></div><div className="bk-product-buyrow"><div className="bk-quantity"><button aria-label="Decrease quantity" onClick={()=>setQuantity(q=>Math.max(1,q-1))}><Minus size={16}/></button><span>{quantity}</span><button aria-label="Increase quantity" onClick={()=>setQuantity(q=>Math.min(Math.max(1,product.stock),q+1))} disabled={quantity>=product.stock}><Plus size={16}/></button></div><button className="bk-btn" disabled={product.stock<=0} onClick={()=>add(product.id,quantity)}>Add to bag <ShoppingBag size={16}/></button><button className={`bk-iconbtn ${saved.includes(product.id)?'active':''}`} style={{border:'1px solid var(--bk-line)',borderRadius:2,minWidth:48}} onClick={()=>toggle(product.id)} aria-label={saved.includes(product.id)?'Remove from wishlist':'Save to wishlist'}><Heart fill={saved.includes(product.id)?'currentColor':'none'}/></button></div><div className="bk-preview-note">Please note: delivery estimates are not guaranteed dates. Checkout is unavailable while payment setup is being connected.</div><details className="bk-panel"><summary>About this listing</summary><p>Product information is drawn from the catalogue. No maker biography or additional product claims have been added.</p></details></div></div></section>{related.length>0&&<section className="bk-section"><div className="bk-sectionhead"><div><span className="bk-eyebrow">From this maker</span><h2>More from {maker?.brand}</h2></div></div><ProductGrid products={related} makers={makers} saved={saved} toggle={toggle}/></section>}</main>;
}
function MakerPage({ maker, catalog, saved, toggle }: { maker?: Maker; catalog: Catalog; saved:string[]; toggle:(id:string)=>void }) {
  if (!maker) return <main className="bk-formpage"><Seo title="Maker not found" description="This maker is not in the current catalogue."/><h1>Maker not found.</h1><Link className="bk-btn" href="/makers">Meet the makers</Link></main>;
  const items = catalog.products.filter(p => p.makerId === maker.id);
  return <main><Seo title={maker.brand} description={`${maker.brand}, ${maker.craft}. Maker story and work from the current catalogue.`}/><section className="bk-section bk-split"><img className="bk-storyimg" src={imageUrl(maker.image)} alt={`${maker.brand} catalogue image`}/><div className="bk-storycopy"><span className="bk-eyebrow">{maker.craft}{catalog.sample?' · sample catalogue':''}</span><h1 style={{fontSize:'clamp(44px,6vw,72px)',margin:'10px 0'}}>{maker.brand}</h1><h2 style={{fontSize:33}}>{maker.tagline}</h2><p>{maker.story}</p><p className="bk-muted">This page shares the maker description provided in the catalogue. No additional biography has been invented.</p>{catalog.sample&&<span className="bk-status">Maker profile · sample catalogue</span>}</div></section><section className="bk-section" style={{paddingTop:0}}><div className="bk-sectionhead"><div><span className="bk-eyebrow">The work</span><h2>Pieces by {maker.brand}</h2></div></div><ProductGrid products={items} makers={catalog.makers} saved={saved} toggle={toggle}/></section></main>;
}
function FinderPage() {
  const mutation = useFindGifts();
  const [step, setStep] = useState(0);
  const [answers, setAnswers] = useState(['','','','']);
  const [budgetPaise,setBudget] = useState(300000);
  const steps = [
    {key:'recipient', title:'Who is this for?', prompt:'A little context can make a gift feel more personal.', options:['parent|A parent','partner|A partner','friend|A friend','colleague|A colleague','self|Myself']},
    {key:'occasion', title:'What brings you here?', prompt:'Or choose “just because”.', options:['diwali|Diwali','wedding|A wedding','birthday|A birthday','thanks|A thank you','housewarming|A new home','justbecause|Just because']},
    {key:'feeling', title:'What should it feel like?', prompt:'Choose the feeling you hope the gift carries.', options:['heart|From the heart','showstopper|A little showstopper','soother|Calm and comforting','thoughtful|Quietly thoughtful','explorer|For the curious']},
    {key:'budget', title:'What feels comfortable?', prompt:'Choose a range. You can change this later.', options:['150000|Under ₹1,500','300000|₹1,500–₹3,000','500000|₹3,000–₹5,000','10000000|Any budget']},
  ];
  const choose=(option:string) => { const value=option.split('|')[0];setAnswers(a=>a.map((v,i)=>i===step?value:v)); if(step===3)setBudget(Number(value)); };
  const next=() => { if(step<3){setStep(s=>s+1);return;} mutation.mutate({data:{recipient:answers[0],occasion:answers[1],feeling:answers[2],budgetPaise}}); };
  return <main className="bk-finder-wrap"><Seo title="Gift finder" description="A guided gift finder with recommendations from the current sample catalogue."/><div className="bk-finder-intro"><span className="bk-eyebrow">A thoughtful place to begin</span><h1>Find a gift with feeling.</h1><p>Four small questions help us look through the catalogue. Recommendations come from this sample catalogue, not live AI.</p></div><div className="bk-finder-card"><aside className="bk-finder-side"><div><span className="bk-eyebrow" style={{color:'#e5c37e'}}>A little guidance</span><h2>Start with what matters.</h2><p>Skip anything you are not sure about. You can go back and change an answer.</p></div><div><strong>Question {Math.min(step+1,4)} of 4</strong><div className="bk-finder-progress">{steps.map((_,i)=><i key={i} className={i<=step?'on':''}/>)}</div></div></aside><section className="bk-finder-content">{mutation.data ? <><span className="bk-eyebrow">Your gift edit</span><h2>A few pieces to consider.</h2><p>{mutation.data.message}</p>{mutation.data.sample&&<p className="bk-status">Recommendations from sample catalogue</p>}{mutation.data.matches.length ? <div className="bk-results">{mutation.data.matches.map(({product,reason}:GiftMatch)=><Link className="bk-resultcard" key={product.id} href={`/products/${product.slug}`}><img src={imageUrl(product.image)} alt=""/><div><strong>{product.name}</strong><small>{reason}</small><b>{money(product.pricePaise)}</b></div></Link>)}</div>:<p className="bk-empty">No matches for this combination. Try a broader budget or another feeling.</p>}<button className="bk-btn secondary" onClick={()=>{mutation.reset();setStep(0)}}>Start again</button></> : <>
    <span className="bk-eyebrow">{steps[step].key}</span><h2>{steps[step].title}</h2><p>{steps[step].prompt}</p><div className="bk-options">{steps[step].options.map(o=>{const [id,label]=o.split('|');return <button className={`bk-option ${answers[step]===id?'chosen':''}`} onClick={()=>choose(o)} key={o}>{label}{answers[step]===id&&<Check size={16}/>}</button>})}</div>{mutation.isError&&<p className="bk-errorbox" role="alert">{errText(mutation.error)}</p>}<div className="bk-finder-controls"><button className="bk-skip" onClick={()=>{if(step>0)setStep(s=>s-1)}} disabled={step===0}>Back</button><div><button className="bk-skip" onClick={()=>{setAnswers(a=>a.map((v,i)=>i===step?'':v));if(step===3)setBudget(10000000);if(step<3)setStep(s=>s+1);else next()}}>Skip</button><button className="bk-btn" disabled={mutation.isPending} onClick={next}>{mutation.isPending?'Finding…':step===3?'Show my ideas':'Continue'} <ArrowRight size={15}/></button></div></div></>}</section></div></main>;
}

function CorporatePage() {
  const create = useCreateBrief();
  const [done,setDone]=useState<{id:string;message:string}|null>(null);
  const [values,setValues]=useState({purpose:'',quantity:'',budget:'',neededBy:'',contactName:'',company:'',email:'',message:''});
  const update=(key:keyof typeof values,value:string)=>setValues(v=>({...v,[key]:value}));
  const submit=(e:FormEvent)=>{e.preventDefault();create.mutate({data:{purpose:values.purpose,quantity:Number(values.quantity),budgetPaise:Math.round(Number(values.budget)*100),neededBy:values.neededBy,contactName:values.contactName,company:values.company,email:values.email,message:values.message}},{onSuccess:r=>setDone(r)});};
  return <main className="bk-formpage"><Seo title="Corporate gifting" description="Share a brief for thoughtful corporate gifting from independent makers."/><span className="bk-eyebrow">For teams and gatherings</span><h1>Gifts that say something.</h1><p>Tell us what you are planning. A brief is only considered received when the service confirms it below; this form does not guarantee availability or delivery timing.</p>{done ? <div className="bk-success" role="status"><h2>Brief received</h2><p>{done.message}</p><small>Reference {done.id}</small></div> : <form className="bk-form" onSubmit={submit}>
    <label>Purpose<input required value={values.purpose} onChange={e=>update('purpose',e.target.value)} maxLength={200} placeholder="A gathering, welcome, thank you…"/></label><label>Quantity<input type="number" min="1" max="100000" required value={values.quantity} onChange={e=>update('quantity',e.target.value)}/></label><label>Approximate total budget (₹)<input type="number" min="1" step="1" required value={values.budget} onChange={e=>update('budget',e.target.value)}/></label><label>Needed by<input type="date" required value={values.neededBy} onChange={e=>update('neededBy',e.target.value)}/></label><label>Your name<input required value={values.contactName} onChange={e=>update('contactName',e.target.value)}/></label><label>Company or organisation<input required value={values.company} onChange={e=>update('company',e.target.value)}/></label><label>Email<input type="email" required value={values.email} onChange={e=>update('email',e.target.value)}/></label><label className="wide">Notes<textarea value={values.message} onChange={e=>update('message',e.target.value)} maxLength={4000} placeholder="Tell us about the occasion, preferences or questions."/></label>{create.isError&&<p className="bk-error" role="alert">{errText(create.error)}</p>}<button className="bk-btn" disabled={create.isPending}>{create.isPending?'Sending brief…':'Send a brief'} <ArrowRight size={16}/></button></form>}</main>;
}
function SellPage({user,v,setV,onSignIn}:{user:User|null;v:SellValues;setV:Dispatch<SetStateAction<SellValues>>;onSignIn:()=>void}) {
  const apply=useApplyToSell();const [done,setDone]=useState<{id:string;message:string}|null>(null);
  const [authError,setAuthError]=useState('');
  const up=(key:keyof typeof v,value:string|boolean)=>setV(x=>({...x,[key]:value}));
  const submit=(e:FormEvent)=>{e.preventDefault();setAuthError('');if(!user?.email_confirmed_at){setAuthError('A verified sign-in is required before submitting a maker application. Your entries are still here.');return;}apply.mutate({data:{brand:v.brand,contactName:v.contactName,phone:v.phone,craft:v.craft,city:v.city,state:v.state,gstRegistered:v.gstRegistered,gstin:v.gstin||undefined,link:v.link||undefined}},{onSuccess:r=>setDone(r)});};
  return <main className="bk-formpage"><Seo title="Sell with Baksa Tales" description="Introduce your handmade work to Baksa Tales."/><span className="bk-eyebrow">For independent makers</span><h1>Introduce your work.</h1><p>Tell us a little about your practice. This is an application for consideration, not a promise of acceptance or a live seller account.</p>{done?<div className="bk-success" role="status"><h2>Application received</h2><p>{done.message}</p><small>Reference {done.id}</small></div>:<form className="bk-form" onSubmit={submit}>
    <label>Brand or studio name<input required maxLength={150} value={v.brand} onChange={e=>up('brand',e.target.value)}/></label><label>Your name<input required maxLength={150} value={v.contactName} onChange={e=>up('contactName',e.target.value)}/></label><label>Phone number<input required pattern="[6-9][0-9]{9}" inputMode="numeric" value={v.phone} onChange={e=>up('phone',e.target.value)} placeholder="10 digit Indian mobile number"/></label><label>Craft or practice<input required maxLength={200} value={v.craft} onChange={e=>up('craft',e.target.value)}/></label><label>City<input required maxLength={100} value={v.city} onChange={e=>up('city',e.target.value)}/></label><label>State<input required maxLength={100} value={v.state} onChange={e=>up('state',e.target.value)}/></label><label className="bk-check wide"><input type="checkbox" checked={v.gstRegistered} onChange={e=>up('gstRegistered',e.target.checked)}/> GST registered</label>{v.gstRegistered&&<label>GSTIN<input maxLength={15} value={v.gstin} onChange={e=>up('gstin',e.target.value)}/></label>}<label className="wide">Website or portfolio link (optional)<input type="url" maxLength={400} value={v.link} onChange={e=>up('link',e.target.value)} placeholder="https://"/></label>{(!user?.email_confirmed_at)&&<p className="bk-panel wide">Maker applications require a verified account. <Link href="/sign-in" onClick={onSignIn}>Sign in or create an account</Link>, then return to send this form.</p>}{authError&&<p className="bk-error" role="alert">{authError}</p>}{apply.isError&&<p className="bk-error" role="alert">{errText(apply.error)}</p>}<button className="bk-btn" disabled={apply.isPending}>{apply.isPending?'Sending application…':'Send application'} <ArrowRight size={16}/></button></form>}</main>;
}

function BagView({ catalog, cart, setCart, checkout = false, runtime }: { catalog: Catalog; cart: CartItem[]; setCart:(items:CartItem[])=>void; checkout?:boolean; runtime?:Runtime }) {
  const entries = cart.map(item=>({item,product:catalog.products.find(p=>p.id===item.productId)})).filter(x=>x.product) as {item:CartItem;product:Product}[];
  const total=entries.reduce((sum,e)=>sum+e.product.pricePaise*e.item.quantity,0);
  const groups = catalog.makers.map(m=>({maker:m,items:entries.filter(e=>e.product.makerId===m.id)})).filter(g=>g.items.length);
  return <main className="bk-formpage"><Seo title={checkout?'Checkout':'Your bag'} description={checkout?'Checkout setup information for your Baksa Tales bag.':'Review the pieces in your Baksa Tales bag.'}/><span className="bk-eyebrow">{checkout?'A note before checkout':'Your considered selection'}</span><h1>{checkout?'Checkout':'Your bag'}</h1>
    {checkout ? <div className="bk-errorbox"><h2 style={{fontSize:30}}>Payment setup is not connected yet.</h2><p>Your bag is still here. No order has been created and no payment has been taken. {runtime?.payments ? 'Payment service is available, but checkout is not yet enabled on this storefront.' : 'The marketplace is not ready to accept payments.'}</p><Link className="bk-btn secondary" href="/bag">Return to your bag</Link></div> : <>
      {!entries.length?<div className="bk-empty"><strong style={{font:'30px var(--bk-display)',color:'var(--bk-ink)'}}>Your bag is waiting for a story.</strong><p>When something feels right, it will be kept here.</p><Link className="bk-btn" href="/shop">Explore the edit</Link></div>:<><div>{groups.map(group=><section className="bk-panel" key={group.maker.id}><h2>From {group.maker.brand}</h2>{group.items.map(({item,product})=><div className="bk-draweritem" key={item.productId}><Link href={`/products/${product.slug}`}><img src={imageUrl(product.image)} alt={product.name}/></Link><div><Link href={`/products/${product.slug}`} style={{font:'20px var(--bk-display)'}}>{product.name}</Link><p>{money(product.pricePaise)}</p><div className="bk-quantity"><button aria-label={`Decrease ${product.name}`} onClick={()=>setCart(cart.map(x=>x.productId===item.productId?{...x,quantity:Math.max(1,x.quantity-1)}:x))}><Minus size={14}/></button><span>{item.quantity}</span><button aria-label={`Increase ${product.name}`} onClick={()=>setCart(cart.map(x=>x.productId===item.productId?{...x,quantity:x.quantity+1}:x))}><Plus size={14}/></button></div></div><button className="bk-iconbtn" aria-label={`Remove ${product.name}`} onClick={()=>setCart(cart.filter(x=>x.productId!==item.productId))}><X size={18}/></button></div>)}</section>)}</div><div className="bk-panel"><div style={{display:'flex',justifyContent:'space-between',fontSize:18}}><span>Subtotal</span><strong>{money(total)}</strong></div><p className="bk-muted">Shipping and final availability are confirmed only when checkout is available.</p><Link className="bk-btn" href="/checkout">Continue to checkout <ArrowRight size={16}/></Link></div></>}</>}
  </main>;
}
function BagDrawer({ open, close, catalog, cart, setCart }: { open:boolean;close:()=>void;catalog:Catalog;cart:CartItem[];setCart:(items:CartItem[])=>void }) {
  const closeRef=useRef(close);closeRef.current=close;
  const dialogRef=useRef<HTMLElement>(null);
  useEffect(()=>{if(!open)return;const old=document.body.style.overflow;document.body.style.overflow='hidden';dialogRef.current?.querySelector<HTMLElement>('button')?.focus();const key=(e:KeyboardEvent)=>{if(e.key==='Escape'){e.preventDefault();closeRef.current()}if(e.key==='Tab'&&dialogRef.current){const a=Array.from(dialogRef.current.querySelectorAll<HTMLElement>('a[href],button:not([disabled]),input')).filter(x=>x.offsetParent!==null);const first=a[0],last=a.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};window.addEventListener('keydown',key);return()=>{document.body.style.overflow=old;window.removeEventListener('keydown',key)}},[open]);
  if(!open)return null;
  const items=cart.map(i=>({i,p:catalog.products.find(p=>p.id===i.productId)})).filter(x=>x.p) as {i:CartItem;p:Product}[];
  return <div className="bk-drawerback" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><aside className="bk-drawer" role="dialog" aria-modal="true" aria-label="Shopping bag" ref={dialogRef}><header className="bk-drawerhead"><h2>Your bag</h2><button className="bk-iconbtn" aria-label="Close bag" onClick={close}><X/></button></header>{items.length? <>{items.map(({i,p})=><div className="bk-draweritem" key={p.id}><img src={imageUrl(p.image)} alt={p.name}/><div><strong>{p.name}</strong><p>{money(p.pricePaise)}</p><div className="bk-quantity"><button aria-label="Decrease quantity" onClick={()=>setCart(cart.map(x=>x.productId===p.id?{...x,quantity:Math.max(1,x.quantity-1)}:x))}><Minus size={14}/></button><span>{i.quantity}</span><button aria-label="Increase quantity" onClick={()=>setCart(cart.map(x=>x.productId===p.id?{...x,quantity:x.quantity+1}:x))}><Plus size={14}/></button></div></div><button className="bk-iconbtn" aria-label={`Remove ${p.name}`} onClick={()=>setCart(cart.filter(x=>x.productId!==p.id))}><X size={17}/></button></div>)}<div style={{marginTop:'auto',borderTop:'1px solid var(--bk-line)',paddingTop:18}}><p>Subtotal <strong style={{float:'right'}}>{money(items.reduce((s,x)=>s+x.p.pricePaise*x.i.quantity,0))}</strong></p><Link className="bk-btn" style={{width:'100%'}} href="/bag" onClick={close}>View bag</Link></div></>:<div className="bk-empty" style={{margin:'auto 0'}}><strong style={{font:'28px var(--bk-display)',color:'var(--bk-ink)'}}>A little room for something meaningful.</strong><p>Your bag is empty.</p><Link className="bk-btn" href="/shop" onClick={close}>Explore the edit</Link></div>}</aside></div>;
}
function SignInPage({ runtime, runtimeLoading, client, user, returnTo }: { runtime?:Runtime;runtimeLoading:boolean;client:SupabaseClient|null;user:User|null;returnTo:string }) {
  const [,navigate]=useLocation();const [signup,setSignup]=useState(false);const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [error,setError]=useState('');const [message,setMessage]=useState('');const [busy,setBusy]=useState(false);
  useEffect(()=>{if(user)navigate(returnTo)},[user,navigate,returnTo]);
  const submit=async(e:FormEvent)=>{e.preventDefault();setError('');setMessage('');if(!client)return;setBusy(true);try{const result=signup?await client.auth.signUp({email,password}):await client.auth.signInWithPassword({email,password});if(result.error)throw result.error;if(signup&&!result.data.session)setMessage('Check your email for the confirmation link.');else if(result.data.user)setMessage('You are signed in.');}catch(e){setError((e as Error).message||'Authentication could not be completed.')}finally{setBusy(false)}};
  return <main className="bk-formpage" style={{maxWidth:690}}><Seo title="Sign in" description="Sign in to your Baksa Tales account."/><span className="bk-eyebrow">A familiar place to return to</span><h1>{signup?'Create your account':'Welcome back.'}</h1><p>Sign in is securely handled by the connected Supabase authentication service.</p>{runtimeLoading?<div className="bk-skeleton"/>:!runtime?.auth||!client?<div className="bk-panel"><h2>Sign-in setup is not connected yet.</h2><p>{runtime?.message || 'The marketplace owner needs to connect Supabase authentication before accounts can be created.'}</p><span className="bk-status">No demo account or simulated login</span></div>:<form className="bk-form" onSubmit={submit}><label className="wide">Email address<input required type="email" autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)}/></label><label className="wide">Password<input required type="password" autoComplete={signup?'new-password':'current-password'} minLength={6} value={password} onChange={e=>setPassword(e.target.value)}/></label>{error&&<p className="bk-error" role="alert">{error}</p>}{message&&<p className="bk-success" role="status">{message}</p>}<button className="bk-btn" disabled={busy}>{busy?'Please wait…':signup?'Create account':'Sign in'}</button><button type="button" className="bk-btn secondary" onClick={()=>{setSignup(v=>!v);setError('');setMessage('')}}>{signup?'I already have an account':'Create an account'}</button></form>}</main>;
}
function AcademyPage(){return <main className="bk-formpage"><Seo title="Baksa Academy" description="Information about upcoming Baksa Academy classes."/><span className="bk-eyebrow">Learn, share, make</span><h1>Baksa Academy.</h1><p>A future home for practical learning around craft, small creative businesses and the thoughtful work of making.</p><div className="bk-panel"><h2>Classes are not open yet.</h2><p>We are shaping the programme. There are no enrolments or scheduled classes to book at this time.</p><Link className="bk-btn secondary" href="/sell">For maker enquiries <ArrowRight size={16}/></Link></div></main>}

const makerLinks=[['Overview','/maker'],['Products','/maker/products'],['Orders','/maker/orders'],['Earnings','/maker/earnings'],['Opportunities','/maker/opportunities'],['Growth tools','/maker/growth'],['Brand profile','/maker/brand']];
function MakerArea({ path, workspace }: { path:string;workspace:Workspace|undefined }) {
  const products=workspace?.products||[];
  if(path==='/maker/products/new'||path.startsWith('/maker/products/')&&path!=='/maker/products'){
    const editingId=path==='/maker/products/new'?undefined:decodeURIComponent(path.split('/').pop()||'');
    const existing=editingId?products.find(p=>p.id===editingId):undefined;
    return <ProductWizard existing={existing} productId={editingId}/>;
  }
  const active = makerLinks.find(x=>x[1]===path)?.[0]||'Overview';
  const section=path==='/maker/products'?'products':path==='/maker/orders'?'orders':path==='/maker/earnings'?'earnings':path==='/maker/opportunities'?'opportunities':path==='/maker/growth'?'growth':path==='/maker/brand'?'brand':'overview';
  return <main className="bk-dashboard"><aside><span className="bk-eyebrow">Maker workspace</span><h2 style={{fontSize:32}}>{workspace?.maker?.brand||'Your studio'}</h2><nav className="bk-dashnav">{makerLinks.map(([label,href])=><Link key={href} href={href} aria-current={active===label?'page':undefined}>{label}</Link>)}</nav></aside><section><span className="bk-eyebrow">{active}</span><h1 style={{fontSize:'clamp(40px,5vw,60px)',margin:'8px 0 20px'}}>{section==='overview'?'Your maker workspace':active}</h1>
    {section==='overview'&&<><p className="bk-muted">A clear view of your work on Baksa Tales.</p><div className="bk-panel"><h2>Products</h2><p>{products.length} products in your workspace. Listing status is shown from the service; draft work is not presented as published.</p><Link className="bk-btn" href="/maker/products/new">Start a product draft <Plus size={16}/></Link></div><div className="bk-panel"><h2>Orders</h2><p>{workspace?.ordersCount ?? 0} orders recorded by the workspace.</p><Link className="bk-textlink" href="/maker/orders">View orders <ArrowRight size={15}/></Link></div></>}
    {section==='products'&&<><p className="bk-muted">Your workspace products. A draft is not live until submitted and reviewed.</p><Link className="bk-btn" href="/maker/products/new">Create a product draft <Plus size={16}/></Link>{products.length?products.map(p=><div className="bk-panel" key={p.id} style={{display:'flex',gap:16,alignItems:'center'}}><img src={imageUrl(p.image||'baksatales-trunk-mark.png')} alt="" style={{width:76,height:76,objectFit:'cover'}}/><div style={{flex:1}}><h2>{p.name}</h2><p>{money(p.pricePaise)} · {p.material}</p><span className="bk-status">{p.status||'Draft'}</span>{p.reviewNote&&<p>{p.reviewNote}</p>}</div><Link className="bk-btn secondary" href={`/maker/products/${p.id}`}>Edit draft</Link></div>):<div className="bk-empty"><strong style={{font:'26px var(--bk-display)',color:'var(--bk-ink)'}}>No products in your workspace.</strong><p>Start with a draft. Product images cannot be uploaded until storage is connected.</p></div>}</>}
    {section==='orders'&&<div className="bk-panel"><h2>{workspace?.ordersCount??0} orders recorded</h2><p>Order details are not available through this workspace service yet. No order rows are invented.</p></div>}
    {section==='earnings'&&<div className="bk-panel"><h2>Earnings are not connected.</h2><p>There is no payout or earnings data in the workspace response. This space will show actual figures when the payout integration is available.</p></div>}
    {section==='opportunities'&&<div className="bk-panel"><h2>Opportunities are coming later.</h2><p>No open briefs or placements are exposed in this workspace yet.</p></div>}
    {section==='growth'&&<MarginCalculator/>}
    {section==='brand'&&<div className="bk-panel"><h2>{workspace?.maker?.brand||'Brand profile'}</h2>{workspace?.maker?<><p>{workspace.maker.tagline}</p><p>{workspace.maker.story}</p><p className="bk-muted">{workspace.maker.craft}</p></>:<p>Scoped brand profile editing is a future capability. No maker profile was returned for this workspace.</p>}</div>}
  </section></main>;
}
function MarginCalculator(){
  const [price,setPrice]=useState(2500);const [materials,setMaterials]=useState(500);const [labour,setLabour]=useState(750);const [fee,setFee]=useState(12);
  const estimate=Math.round(price-(price*fee/100)-materials-labour);
  return <div className="bk-panel"><span className="bk-status">Local estimate only · not a payout forecast</span><h2>Try a price, see the shape.</h2><p>Change the assumptions. Nothing is saved or sent to the marketplace.</p><div className="bk-form"><label>Sale price (₹)<input type="number" min="0" value={price} onChange={e=>setPrice(Number(e.target.value))}/></label><label>Materials (₹)<input type="number" min="0" value={materials} onChange={e=>setMaterials(Number(e.target.value))}/></label><label>Your time (₹)<input type="number" min="0" value={labour} onChange={e=>setLabour(Number(e.target.value))}/></label><label>Estimated platform fee (%)<input type="number" min="0" max="100" step=".5" value={fee} onChange={e=>setFee(Number(e.target.value))}/></label></div><div className="bk-panel" style={{background:'var(--bk-teal)',color:'var(--bk-paper)'}}><small>Illustrative remainder after entered costs and fee</small><h2>{money(estimate*100)}</h2><small>Rates are editable assumptions, not Baksa Tales fee terms.</small></div></div>;
}
function ProductWizard({ existing, productId }: { existing?:Product;productId?:string }) {
  const save=useSaveProduct();const submitProduct=useSubmitProduct();const [,navigate]=useLocation();
  const queryClient=useQueryClient();
  const refresh=()=>{void queryClient.invalidateQueries({queryKey:getGetCatalogQueryKey()});void queryClient.invalidateQueries({queryKey:getGetWorkspaceQueryKey()});};
  const [step,setStep]=useState(0);const [savedId,setSavedId]=useState<string|undefined>(existing?.id);const [formIssue,setFormIssue]=useState('');
  const [v,setV]=useState({name:existing?.name||'',price:String(existing?existing.pricePaise/100:''),stock:String(existing?.stock??''),material:existing?.material||'',description:existing?.description||'',dispatch:String(existing?.dispatchDays??''),confirm:false});
  const up=(key:keyof typeof v,value:string|boolean)=>setV(old=>({...old,[key]:value}));
  const steps=['Name your piece','Set a price','Availability','Materials','Describe your work','Dispatch preparation','Confirm the facts'];
  useEffect(()=>{if(existing)setV({name:existing.name,price:String(existing.pricePaise/100),stock:String(existing.stock),material:existing.material,description:existing.description,dispatch:String(existing.dispatchDays),confirm:false})},[existing]);
  const current = !productId || !!existing && ['draft','changes','needs_changes'].includes(existing.status||'');
  const validate=()=>{const invalidStep=!v.name.trim()?0:!Number.isFinite(Number(v.price))||Number(v.price)<=0?1:!v.stock.trim()||!Number.isInteger(Number(v.stock))||Number(v.stock)<0?2:!v.material.trim()?3:!v.description.trim()?4:!Number.isInteger(Number(v.dispatch))||Number(v.dispatch)<1||Number(v.dispatch)>60?5:!v.confirm?6:-1;if(invalidStep>=0){setStep(invalidStep);setFormIssue(invalidStep===6?'Please confirm the accuracy of the listing facts before saving.':'Complete this step with a valid value before saving.');return false}setFormIssue('');return true};
  const saveDraft=()=>{if(!validate())return;save.mutate({data:{...(savedId?{id:savedId}:{}),name:v.name,pricePaise:Math.round(Number(v.price)*100),stock:Number(v.stock),material:v.material,description:v.description,dispatchDays:Number(v.dispatch),factualConfirmation:v.confirm}},{onSuccess:r=>{setSavedId(r.id);refresh();navigate('/maker/products');}});};
  const saveAndSubmit=()=>{if(!validate())return;save.mutate({data:{...(savedId?{id:savedId}:{}),name:v.name,pricePaise:Math.round(Number(v.price)*100),stock:Number(v.stock),material:v.material,description:v.description,dispatchDays:Number(v.dispatch),factualConfirmation:v.confirm}},{onSuccess:r=>{setSavedId(r.id);refresh();submitProduct.mutate({id:r.id},{onSuccess:()=>{refresh();navigate('/maker/products')}});}});};
  if(!current)return <main className="bk-formpage"><Seo title="Draft not found" description="Draft unavailable."/><h1>That draft is not in your workspace.</h1><p>Only products returned by your account workspace can be edited.</p><Link className="bk-btn" href="/maker/products">Back to products</Link></main>;
  const showUpload=step===5;
  return <main className="bk-formpage"><Seo title={existing?'Edit product draft':'New product draft'} description="Build a product draft for maker review."/><span className="bk-eyebrow">Maker workspace · {existing?'Edit draft':'New listing draft'}</span><h1>{existing?`Edit ${existing.name}`:'A new piece, step by step.'}</h1><div className="bk-steps">{steps.map((s,i)=><span key={s} className={`bk-step ${i===step?'active':''}`}>{i+1}. {s}</span>)}</div><div className="bk-panel"><h2>{steps[step]}</h2>
    {step===0&&<label>Listing name<input className="bk-input" required maxLength={200} value={v.name} onChange={e=>up('name',e.target.value)} placeholder="Name the piece"/></label>}
    {step===1&&<label>Price in rupees<input className="bk-input" type="number" required min="1" step=".01" value={v.price} onChange={e=>up('price',e.target.value)}/><small>Entered as rupees; the service receives integer paise.</small></label>}
    {step===2&&<label>Available stock<input className="bk-input" type="number" required min="0" value={v.stock} onChange={e=>up('stock',e.target.value)}/></label>}
    {step===3&&<label>Materials and components<textarea className="bk-input" required maxLength={500} value={v.material} onChange={e=>up('material',e.target.value)}/></label>}
    {step===4&&<><label>Factual product description<textarea className="bk-input" required maxLength={5000} value={v.description} onChange={e=>up('description',e.target.value)} placeholder="Describe the piece, its materials, dimensions or process you can verify."/></label><p className="bk-status">AI description assistance is unavailable. Write a factual description manually.</p></>}
    {showUpload&&<><label>Dispatch preparation days<input className="bk-input" type="number" required min="1" max="60" value={v.dispatch} onChange={e=>up('dispatch',e.target.value)}/></label><div className="bk-panel"><h2>Images are not connected.</h2><p>Product image upload is unavailable until marketplace storage is configured. A draft can still be saved without uploading an image.</p></div></>}
    {step===6&&<><p>Review the listing information you entered before saving a draft.</p><div className="bk-panel"><strong>{v.name || 'Untitled piece'}</strong><p>{v.material}</p><p>{v.description}</p><p>{v.price?`₹${v.price}`:''} · {v.stock||'—'} available · {v.dispatch||'—'} dispatch preparation days</p></div><label className="bk-check"><input type="checkbox" checked={v.confirm} onChange={e=>up('confirm',e.target.checked)}/> I confirm these listing facts are accurate to the best of my knowledge.</label><p className="bk-muted">Saving creates a draft only. It does not publish the product.</p></>}
    {formIssue&&<p className="bk-error" role="alert">{formIssue}</p>}{(save.isError||submitProduct.isError)&&<p className="bk-error" role="alert">{errText(save.error||submitProduct.error)}</p>}
    <div style={{display:'flex',justifyContent:'space-between',gap:10,marginTop:24}}><button className="bk-btn secondary" disabled={step===0} onClick={()=>setStep(s=>Math.max(s-1,0))}><ArrowLeft size={15}/> Back</button><div style={{display:'flex',gap:8}}><button className="bk-btn secondary" onClick={saveDraft} disabled={save.isPending||submitProduct.isPending}>Save draft</button>{step<6?<button className="bk-btn" onClick={()=>setStep(s=>Math.min(s+1,6))}>Next <ArrowRight size={15}/></button>:<button className="bk-btn" disabled={!v.confirm||save.isPending||submitProduct.isPending} onClick={saveAndSubmit}>{submitProduct.isPending?'Submitting…':'Save and submit for review'}</button>}</div></div>
  </div></main>;
}
function AdminArea({ path, workspace, catalog }: { path:string;workspace:Workspace|undefined;catalog:Catalog }) {
  const review=useReviewProduct();const [,setLocation]=useLocation();const queryClient=useQueryClient();
  const links=[['Overview','/admin'],['Reviews','/admin/reviews'],['Applications','/admin/applications'],['Enquiries','/admin/enquiries'],['Orders','/admin/orders'],['Payouts','/admin/payouts']];
  const active=links.find(i=>i[1]===path)?.[0]||'Overview';
  return <main className="bk-dashboard"><aside><span className="bk-eyebrow">Marketplace operations</span><h2 style={{fontSize:32}}>Admin</h2><nav className="bk-dashnav">{links.map(([t,u])=><Link key={u} href={u}>{t}</Link>)}</nav></aside><section><span className="bk-eyebrow">{active}</span><h1 style={{fontSize:'clamp(40px,5vw,60px)',margin:'8px 0 20px'}}>{active}</h1>
    {path==='/admin/reviews'?<><p className="bk-muted">Product facts are reviewed against the five checks. Only products marked for review by the actual catalog appear here.</p>{catalog.products.filter(p=>p.status==='pending_review'||p.status==='review').map(p=><ReviewRow key={p.id} product={p} busy={review.isPending} onReview={data=>review.mutate({data},{onSuccess:()=>{void queryClient.invalidateQueries({queryKey:getGetCatalogQueryKey()});void queryClient.invalidateQueries({queryKey:getGetWorkspaceQueryKey()});setLocation('/admin/reviews')}})}/>)}{!catalog.products.some(p=>p.status==='pending_review'||p.status==='review')&&<div className="bk-empty"><strong style={{font:'26px var(--bk-display)',color:'var(--bk-ink)'}}>No review queue was returned.</strong><p>This workspace does not currently expose products awaiting review. No approvals have been fabricated.</p></div>}{review.isError&&<p className="bk-errorbox">{errText(review.error)}</p>}</>:path==='/admin'?
      <><p className="bk-muted">Workspace-level information from the authenticated service.</p><div className="bk-panel"><h2>Applications</h2><p>{workspace?.applicationsCount ?? 0} recorded by this workspace.</p></div><div className="bk-panel"><h2>Corporate briefs</h2><p>{workspace?.briefsCount ?? 0} recorded by this workspace.</p></div><div className="bk-panel"><h2>Orders</h2><p>{workspace?.ordersCount ?? 0} recorded by this workspace.</p></div></>:<div className="bk-panel"><h2>{active} integration is not connected.</h2><p>The current workspace API exposes counts only. It does not provide records or safe actions for this section, so no fictional approvals, enquiries, orders or payouts are shown.</p><p>Current available count: {path==='/admin/applications'?workspace?.applicationsCount:path==='/admin/enquiries'?workspace?.briefsCount:path==='/admin/orders'?workspace?.ordersCount:'—'}</p></div>}
  </section></main>;
}
function ReviewRow({product,busy,onReview}:{product:Product;busy:boolean;onReview:(data:{productId:string;decision:'approved'|'changes';handmade:boolean;material:boolean;photos:boolean;price:boolean;story:boolean;note:string})=>void}){
  const [checks,setChecks]=useState([false,false,false,false,false]);const [note,setNote]=useState('');
  const labels=['Handmade origin confirmed','Materials match description','Photos represent item','Price reviewed','Story / description factual'];
  return <article className="bk-panel"><div style={{display:'flex',gap:18,alignItems:'center'}}><img src={imageUrl(product.image)} alt="" style={{width:88,height:88,objectFit:'cover'}}/><div><h2>{product.name}</h2><p>{product.category} · {money(product.pricePaise)}</p><p>{product.reviewNote}</p></div></div><div>{labels.map((l,i)=><label className="bk-check" key={l}><input type="checkbox" checked={checks[i]} onChange={e=>setChecks(c=>c.map((v,j)=>j===i?e.target.checked:v))}/>{l}</label>)}</div><label>Review note<textarea className="bk-input" maxLength={3000} value={note} onChange={e=>setNote(e.target.value)} placeholder="Record what needs attention."/></label><div style={{display:'flex',gap:8,marginTop:12}}><button className="bk-btn" disabled={busy||!checks.every(Boolean)} onClick={()=>onReview({productId:product.id,decision:'approved',handmade:checks[0],material:checks[1],photos:checks[2],price:checks[3],story:checks[4],note})}>Approve after checks</button><button className="bk-btn secondary" disabled={busy} onClick={()=>onReview({productId:product.id,decision:'changes',handmade:checks[0],material:checks[1],photos:checks[2],price:checks[3],story:checks[4],note})}>Request changes</button></div></article>;
}

function SecureGate({runtime,runtimeLoading,ready,user,workspace,workspaceLoading,workspaceError,retryWorkspace,roles,children}:{runtime?:Runtime;runtimeLoading:boolean;ready:boolean;user:User|null;workspace:Workspace|undefined;workspaceLoading:boolean;workspaceError:unknown;retryWorkspace:()=>void;roles:string[];children:ReactNode}){
  if(runtimeLoading)return <main className="bk-formpage"><div className="bk-skeleton"/></main>;
  if(!runtime?.auth)return <main className="bk-formpage"><Seo title="Workspace setup" description="Secure workspace access setup information."/><span className="bk-eyebrow">Private workspace</span><h1>Access is not connected.</h1><p>{runtime?.message||'Supabase authentication is not configured for this marketplace.'}</p><div className="bk-panel"><p>Workspace pages remain protected until the owner connects Supabase and assigns real roles. No demo login or role switch is available.</p><Link className="bk-btn secondary" href="/">Return to the shop</Link></div></main>;
  if(!ready)return <main className="bk-formpage"><Seo title="Checking access" description="Checking secure workspace access."/><div className="bk-skeleton"/></main>;
  if(!user)return <main className="bk-formpage"><Seo title="Sign in required" description="Sign in to continue to your workspace."/><span className="bk-eyebrow">Private workspace</span><h1>Please sign in first.</h1><p>Your private pages use your real verified account and workspace role.</p><Link className="bk-btn" href="/sign-in">Continue to sign in <ArrowRight size={16}/></Link></main>;
  if(workspaceLoading)return <main className="bk-formpage"><div className="bk-skeleton"/></main>;
  if(workspaceError)return <main className="bk-formpage"><Seo title="Workspace unavailable" description="Workspace access could not be confirmed."/><h1>We could not confirm this workspace.</h1><p className="bk-errorbox">{errText(workspaceError)}</p><p>No role or account access is assumed when the service cannot confirm it.</p><button className="bk-btn secondary" onClick={retryWorkspace}>Try again</button></main>;
  if(!roles.some(r=>workspace?.roles.includes(r)))return <main className="bk-formpage"><Seo title="Access unavailable" description="This account does not have the required workspace role."/><h1>This workspace is not available to this account.</h1><p>Access is determined by roles returned from the API workspace, not a public role switch.</p><Link className="bk-btn secondary" href="/">Return to the shop</Link></main>;
  return <>{children}</>;
}
function LoadingError({retry}:{retry:()=>void}){return <div className="bk-formpage"><Seo title="Catalogue unavailable" description="Catalogue data could not be loaded."/><div className="bk-errorbox"><h2>The catalogue is taking a moment.</h2><p>We could not load the current marketplace catalogue. No substitute products have been added.</p><button className="bk-btn secondary" onClick={retry}>Try again</button></div></div>}

export default function BaksaApp(){
  const [path,setLocation]=useLocation();const queryClient=useQueryClient();
  const runtimeQuery=useGetRuntime();const runtime=runtimeQuery.data;
  const catalogQuery=useGetCatalog();const catalog=catalogQuery.data;
  const [cart,setCart]=useState<CartItem[]>(()=>readList('baksa-cart',validCart,[]));
  const [sellDraft,setSellDraft]=useState<SellValues>({brand:'',contactName:'',phone:'',craft:'',city:'',state:'',gstRegistered:false,gstin:'',link:''});
  const [saved,setSaved]=useState<string[]>(()=>readList('baksa-wishlist',validString,[]));
  const [bagOpen,setBagOpen]=useState(false);const [story,setStory]=useState<StoryKey|null>(null);
  const [toast,setToast]=useState('');
  const [user,setUser]=useState<User|null>(null);const [authReady,setAuthReady]=useState(false);
  const [authReturn,setAuthReturn]=useState('/account');
  const previousId=useRef<string|null|undefined>(undefined);
  const supabase=useMemo(()=>runtime?.auth&&runtime.supabaseUrl&&runtime.supabaseAnonKey?createClient(runtime.supabaseUrl,runtime.supabaseAnonKey):null,[runtime?.auth,runtime?.supabaseUrl,runtime?.supabaseAnonKey]);
  useEffect(()=>{localStorage.setItem('baksa-cart',JSON.stringify(cart))},[cart]);
  useEffect(()=>{localStorage.setItem('baksa-wishlist',JSON.stringify(saved))},[saved]);
  useEffect(()=>{
    if(!supabase){setAuthReady(true);setUser(null);setAuthTokenGetter(null);return;}
    setAuthReady(false);
    setAuthTokenGetter(async()=> (await supabase.auth.getSession()).data.session?.access_token ?? null);
    const {data:{subscription}}=supabase.auth.onAuthStateChange((_event,session)=>{const next=session?.user||null;setUser(next);setAuthReady(true);});
    supabase.auth.getSession().then(({data,error})=>{setUser(error?null:data.session?.user||null);setAuthReady(true);});
    return ()=>{subscription.unsubscribe();setAuthTokenGetter(null)};
  },[supabase]);
  useEffect(()=>{const id=user?.id||null;if(previousId.current!==undefined&&id!==previousId.current)queryClient.clear();previousId.current=id},[user?.id,queryClient]);
  const workspaceQuery=useGetWorkspace({query:{queryKey:getGetWorkspaceQueryKey(),enabled:!!user}});
  const workspace=workspaceQuery.data;
  const totalItems=cart.reduce((sum,x)=>sum+x.quantity,0);
  const toggleSave=(id:string)=>setSaved(s=>s.includes(id)?s.filter(x=>x!==id):[...s,id]);
  const addToBag=(id:string,quantity:number)=>{setCart(old=>old.some(x=>x.productId===id)?old.map(x=>x.productId===id?{...x,quantity:x.quantity+quantity}:x):[...old,{productId:id,quantity}]);setToast('Added to your bag');window.setTimeout(()=>setToast(''),2200)};
  const route=path.replace(/\/+$/,'')||'/';
  let content:ReactNode;
  const catContent=()=>catalogQuery.isError?<LoadingError retry={()=>catalogQuery.refetch()}/>:<main className="bk-formpage"><div className="bk-skeleton"/></main>;
  if(route==='/') content=<HomePage catalog={catalog} saved={saved} toggle={toggleSave} setStory={setStory} catalogError={catalogQuery.isError?errText(catalogQuery.error):undefined} retryCatalog={()=>void catalogQuery.refetch()}/>;
  else if(route==='/shop'||route==='/edit') content=catalog? <ShopPage catalog={catalog} saved={saved} toggle={toggleSave}/>:catContent();
  else if(route==='/makers') content=catalog?<MakersPage catalog={catalog}/>:catContent();
  else if(route.startsWith('/makers/')) content=catalog?<MakerPage maker={catalog.makers.find(m=>m.slug===decodeURIComponent(route.slice('/makers/'.length)))} catalog={catalog} saved={saved} toggle={toggleSave}/>:catContent();
  else if(route.startsWith('/products/')) content=catalog?<ProductPage catalog={catalog} product={catalog.products.find(p=>p.slug===decodeURIComponent(route.slice('/products/'.length)))} makers={catalog.makers} saved={saved} toggle={toggleSave} add={addToBag}/>:catContent();
  else if(route==='/gift-finder') content=catalog?<FinderPage/>:catContent();
  else if(route==='/wishlist') content=<main className="bk-formpage"><Seo title="Your wishlist" description="Your saved pieces in this browser."/><span className="bk-eyebrow">Saved for another day</span><h1>Your wishlist.</h1>{catalog ? <ProductGrid products={catalog.products.filter(p=>saved.includes(p.id))} makers={catalog.makers} saved={saved} toggle={toggleSave}/>:catContent()}</main>;
  else if(route==='/bag') content=catalog?<BagView catalog={catalog} cart={cart} setCart={setCart}/>:catContent();
  else if(route==='/checkout') content=<BagView catalog={catalog||{sample:true,products:[],makers:[]}} cart={cart} setCart={setCart} checkout runtime={runtime}/>;
  else if(route==='/corporate') content=<CorporatePage/>;
  else if(route==='/sell') content=<SellPage user={user} v={sellDraft} setV={setSellDraft} onSignIn={()=>setAuthReturn('/sell')}/>;
  else if(route==='/academy') content=<AcademyPage/>;
  else if(route==='/sign-in') content=<SignInPage runtime={runtime} runtimeLoading={runtimeQuery.isLoading} client={supabase} user={user} returnTo={authReturn}/>;
  else if(route==='/account') content=<SecureGate runtime={runtime} runtimeLoading={runtimeQuery.isLoading} ready={authReady} user={user} workspace={workspace} workspaceLoading={workspaceQuery.isLoading} workspaceError={workspaceQuery.error} retryWorkspace={()=>void workspaceQuery.refetch()} roles={['buyer','maker','admin']}><main className="bk-formpage"><Seo title="Your account" description="Your Baksa Tales account and order summary."/><span className="bk-eyebrow">Your place at Baksa Tales</span><h1>Your account.</h1><div className="bk-panel"><h2>{user?.email}</h2><p>Signed in with your secure Supabase account.</p><span className="bk-status">{user?.email_confirmed_at?'Email verified':'Email verification pending'}</span></div><div className="bk-panel"><h2>Your orders</h2><p>{workspace?.ordersCount ?? 0} orders are recorded for this account. Individual order details are not available yet.</p></div><button className="bk-btn secondary" onClick={async()=>{await supabase?.auth.signOut();setLocation('/')}}>Sign out</button></main></SecureGate>;
  else if(route==='/maker'||route.startsWith('/maker/')) content=<SecureGate runtime={runtime} runtimeLoading={runtimeQuery.isLoading} ready={authReady} user={user} workspace={workspace} workspaceLoading={workspaceQuery.isLoading} workspaceError={workspaceQuery.error} retryWorkspace={()=>void workspaceQuery.refetch()} roles={['maker']}><MakerArea path={route} workspace={workspace}/></SecureGate>;
  else if(route==='/admin'||route.startsWith('/admin/')) content=<SecureGate runtime={runtime} runtimeLoading={runtimeQuery.isLoading} ready={authReady} user={user} workspace={workspace} workspaceLoading={workspaceQuery.isLoading} workspaceError={workspaceQuery.error} retryWorkspace={()=>void workspaceQuery.refetch()} roles={['admin']}><AdminArea path={route} workspace={workspace} catalog={catalog||{sample:true,products:[],makers:[]}}/></SecureGate>;
  else content=<main className="bk-formpage"><Seo title="Page not found" description="This Baksa Tales page does not exist."/><span className="bk-eyebrow">A wrong turn</span><h1>This page is not in the baksa.</h1><p>The address may have changed, or the page has not been made available.</p><Link className="bk-btn" href="/">Back to the beginning</Link></main>;
  return <Frame bagCount={totalItems} savedCount={saved.length} onBag={()=>setBagOpen(true)}>{content}{catalog&&<BagDrawer open={bagOpen} close={()=>setBagOpen(false)} catalog={catalog} cart={cart} setCart={setCart}/>}{story&&<StoryViewer id={story} close={()=>setStory(null)} catalog={catalog}/>}{toast&&<div className="bk-toast" role="status">{toast}</div>}</Frame>;
}
